    totalmarksFun(object) {

        if (object != undefined) {
            let tot_marks = (parseInt(object.correct) + parseInt(object.wrong) + parseInt(object.not_answered)) * parseInt(object.pMarks);
            if (!isNaN(tot_marks)) {
                return tot_marks
            }
            else {
                return "0";
            }
        }


    }
    correctmarksFun(object) {
        let data = "";
        if (object != undefined) {
            let correct_marks = parseInt(object.correct) * parseInt(object.pMarks);
            let negative_marks = parseInt(object.wrong) * parseInt(object.nMarks);
            data = parseInt(correct_marks) - parseInt(negative_marks);
        }
        if (!isNaN(data)) {
            return data
        }
        else {
            return "0";
        }

    }
    graphValue() {
        let data = "";
        if (this.props.getStudentSessions.getStudentSessions[0] != undefined) {
            data = parseInt(this.props.getStudentSessions.getStudentSessions[0].correct_marks) - parseInt(this.props.getStudentSessions.getStudentSessions[0].negative_marks);
        }
        console.log("graphValue123", data);
        return data;

    }
    examNameFun() {
        console.log("this.props.history.location.state.examtype", this.props.history.location.state.examtype);
        if (this.props.history.location.state.examtype == "schedule_exam" || this.props.history.location.state.examtype == "schedule" || this.props.history.location.state.examtype == "schedulehome") {
            return "Schedule Exam";

        }
        else if (this.props.history.location.state.examtype == "custom") {
            return "Custom Exam";
        }
        else if (this.props.history.location.state.examtype == "error_exam" || this.props.history.location.state.examtype == "error") {
            return "Error Exam";
        }
        else if (this.props.history.location.state.examtype == "previous_exam" || this.props.history.location.state.examtype == "previous") {
            return "Previous Exam";
        }
        else {
            return "Custom Exam";
        }
    }
    windowClose=()=>{
        window.close();
    }
